import os, subprocess

base = "/tmp/aion"
os.makedirs(f"{base}/migrations/init", exist_ok=True)

# Recrear migración SQL completa
sql = """-- AION Workforce v1.0 - Schema multi-tenant con RLS + Auditoria inmutable
-- Fuentes: ET (BOE-A-2015-11430), Dir 2003/88/CE, RD 1561/1995 (BOE-A-1995-21346)

CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- UUIDv7 generator
CREATE OR REPLACE FUNCTION uuidv7() RETURNS uuid AS $$
DECLARE ts bigint; b bytea;
BEGIN
    ts := (extract(epoch FROM clock_timestamp()) * 1000)::bigint;
    b := gen_random_bytes(16);
    b := set_byte(b, 0, (ts >> 40)::int);
    b := set_byte(b, 1, ((ts >> 32) & 255)::int);
    b := set_byte(b, 2, ((ts >> 24) & 255)::int);
    b := set_byte(b, 3, ((ts >> 16) & 255)::int);
    b := set_byte(b, 4, ((ts >> 8) & 255)::int);
    b := set_byte(b, 5, (ts & 255)::int);
    b := set_byte(b, 6, ((get_byte(b, 6) & 15) | 112));
    b := set_byte(b, 8, ((get_byte(b, 8) & 63) | 128));
    RETURN encode(b, 'hex')::uuid;
END; $$ LANGUAGE plpgsql VOLATILE;

-- TENANTS
CREATE TABLE tenants (
    id UUID PRIMARY KEY DEFAULT uuidv7(),
    name TEXT NOT NULL,
    slug TEXT NOT NULL UNIQUE,
    jurisdiction TEXT NOT NULL DEFAULT 'ES',
    timezone TEXT NOT NULL DEFAULT 'Europe/Madrid',
    currency TEXT NOT NULL DEFAULT 'EUR',
    plan TEXT NOT NULL DEFAULT 'starter',
    status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','suspended','deleted')),
    settings JSONB NOT NULL DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- USERS
CREATE TABLE users (
    id UUID PRIMARY KEY DEFAULT uuidv7(),
    email TEXT NOT NULL UNIQUE,
    password_hash TEXT,
    full_name TEXT NOT NULL,
    is_active BOOLEAN NOT NULL DEFAULT true,
    mfa_enabled BOOLEAN NOT NULL DEFAULT false,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- TENANT_ROLES
CREATE TABLE tenant_roles (
    id UUID PRIMARY KEY DEFAULT uuidv7(),
    tenant_id UUID NOT NULL REFERENCES tenants(id),
    user_id UUID NOT NULL REFERENCES users(id),
    role TEXT NOT NULL CHECK (role IN ('owner','admin','squad_lead','operator','employee','auditor','billing','integration')),
    granted_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at TIMESTAMPTZ,
    UNIQUE(tenant_id, user_id, role)
);

-- EMPLOYEES
CREATE TABLE employees (
    id UUID PRIMARY KEY DEFAULT uuidv7(),
    tenant_id UUID NOT NULL REFERENCES tenants(id),
    employee_code TEXT NOT NULL,
    full_name TEXT NOT NULL,
    hire_date DATE NOT NULL,
    contract_type TEXT NOT NULL DEFAULT 'indefinite',
    weekly_hours NUMERIC(4,1) NOT NULL DEFAULT 40.0,
    is_minor BOOLEAN NOT NULL DEFAULT false,
    is_night_worker BOOLEAN NOT NULL DEFAULT false,
    skills JSONB NOT NULL DEFAULT '[]',
    status TEXT NOT NULL DEFAULT 'active',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE(tenant_id, employee_code)
);

-- SHIFTS
CREATE TABLE shifts (
    id UUID PRIMARY KEY DEFAULT uuidv7(),
    tenant_id UUID NOT NULL REFERENCES tenants(id),
    employee_id UUID NOT NULL REFERENCES employees(id),
    shift_date DATE NOT NULL,
    start_time TIMESTAMPTZ NOT NULL,
    end_time TIMESTAMPTZ NOT NULL,
    shift_type TEXT NOT NULL DEFAULT 'regular',
    status TEXT NOT NULL DEFAULT 'scheduled' CHECK (status IN ('scheduled','confirmed','completed','cancelled','swapped')),
    required_skills JSONB NOT NULL DEFAULT '[]',
    version INTEGER NOT NULL DEFAULT 1,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ABSENCES
CREATE TABLE absences (
    id UUID PRIMARY KEY DEFAULT uuidv7(),
    tenant_id UUID NOT NULL REFERENCES tenants(id),
    employee_id UUID NOT NULL REFERENCES employees(id),
    absence_type TEXT NOT NULL,
    start_date DATE NOT NULL,
    end_date DATE NOT NULL,
    status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected','cancelled')),
    approved_by UUID REFERENCES users(id),
    impact_coverage BOOLEAN NOT NULL DEFAULT true,
    impact_payroll BOOLEAN NOT NULL DEFAULT true,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (end_date >= start_date)
);

-- COMPLIANCE_RULES (motor legal versionado)
CREATE TABLE compliance_rules (
    id UUID PRIMARY KEY DEFAULT uuidv7(),
    rule_code TEXT NOT NULL UNIQUE,
    name TEXT NOT NULL,
    jurisdiction TEXT NOT NULL,
    norm_name TEXT NOT NULL,
    article_reference TEXT NOT NULL,
    source_url TEXT NOT NULL,
    severity TEXT NOT NULL CHECK (severity IN ('info','warning','hard_stop')),
    parameters JSONB NOT NULL DEFAULT '{}',
    effective_from DATE NOT NULL,
    effective_to DATE,
    version INTEGER NOT NULL DEFAULT 1,
    status TEXT NOT NULL DEFAULT 'active',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- COMPLIANCE_VIOLATIONS
CREATE TABLE compliance_violations (
    id UUID PRIMARY KEY DEFAULT uuidv7(),
    tenant_id UUID NOT NULL REFERENCES tenants(id),
    rule_id UUID NOT NULL REFERENCES compliance_rules(id),
    employee_id UUID REFERENCES employees(id),
    shift_id UUID REFERENCES shifts(id),
    violation_date DATE NOT NULL,
    computed_value NUMERIC(10,2),
    threshold_value NUMERIC(10,2),
    severity TEXT NOT NULL,
    explanation TEXT NOT NULL,
    overridden BOOLEAN NOT NULL DEFAULT false,
    override_reason TEXT,
    override_by UUID REFERENCES users(id),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- AUDIT_LOGS (INMUTABLE)
CREATE TABLE audit_logs (
    id UUID PRIMARY KEY DEFAULT uuidv7(),
    tenant_id UUID NOT NULL,
    actor_type TEXT NOT NULL DEFAULT 'user',
    actor_id UUID,
    action TEXT NOT NULL,
    resource_type TEXT NOT NULL,
    resource_id UUID,
    before_state JSONB,
    after_state JSONB,
    metadata JSONB NOT NULL DEFAULT '{}',
    occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    hash TEXT NOT NULL,
    previous_hash TEXT NOT NULL
);

-- Triggers anti-modificacion
CREATE OR REPLACE FUNCTION prevent_audit_mod() RETURNS trigger AS $$
BEGIN RAISE EXCEPTION 'audit_logs es inmutable: % no permitido', TG_OP; RETURN NULL; END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_audit_no_update BEFORE UPDATE ON audit_logs FOR EACH ROW EXECUTE FUNCTION prevent_audit_mod();
CREATE TRIGGER trg_audit_no_delete BEFORE DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION prevent_audit_mod();

-- Hash chain
CREATE OR REPLACE FUNCTION compute_audit_hash() RETURNS trigger AS $$
DECLARE prev TEXT; payload TEXT;
BEGIN
    SELECT hash INTO prev FROM audit_logs ORDER BY occurred_at DESC, id DESC LIMIT 1;
    IF prev IS NULL THEN prev := 'GENESIS'; END IF;
    payload := COALESCE(NEW.tenant_id::text,'') || '|' || NEW.action || '|' || NEW.resource_type || '|' || COALESCE(NEW.resource_id::text,'') || '|' || NEW.occurred_at::text || '|' || prev;
    NEW.previous_hash := prev;
    NEW.hash := encode(digest(payload, 'sha256'), 'hex');
    RETURN NEW;
END; $$ LANGUAGE plpgsql;

CREATE TRIGGER trg_audit_hash BEFORE INSERT ON audit_logs FOR EACH ROW EXECUTE FUNCTION compute_audit_hash();

-- RTA_EVENTS
CREATE TABLE rta_events (
    id UUID PRIMARY KEY DEFAULT uuidv7(),
    tenant_id UUID NOT NULL REFERENCES tenants(id),
    employee_id UUID REFERENCES employees(id),
    event_type TEXT NOT NULL,
    payload JSONB NOT NULL DEFAULT '{}',
    idempotency_key TEXT UNIQUE,
    occurred_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- PAYROLL_RULES
CREATE TABLE payroll_rules (
    id UUID PRIMARY KEY DEFAULT uuidv7(),
    tenant_id UUID NOT NULL REFERENCES tenants(id),
    rule_code TEXT NOT NULL,
    name TEXT NOT NULL,
    rule_type TEXT NOT NULL,
    parameters JSONB NOT NULL DEFAULT '{}',
    effective_from DATE NOT NULL,
    version INTEGER NOT NULL DEFAULT 1,
    status TEXT NOT NULL DEFAULT 'active',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE(tenant_id, rule_code, version)
);

-- PAYROLLS (ledger inmutable)
CREATE TABLE payrolls (
    id UUID PRIMARY KEY DEFAULT uuidv7(),
    tenant_id UUID NOT NULL REFERENCES tenants(id),
    employee_id UUID NOT NULL REFERENCES employees(id),
    period_start DATE NOT NULL,
    period_end DATE NOT NULL,
    status TEXT NOT NULL DEFAULT 'draft',
    entries JSONB NOT NULL DEFAULT '[]',
    total_gross_cents BIGINT NOT NULL DEFAULT 0,
    total_net_cents BIGINT NOT NULL DEFAULT 0,
    currency TEXT NOT NULL DEFAULT 'EUR',
    version INTEGER NOT NULL DEFAULT 1,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ============ ROW LEVEL SECURITY ============
ALTER TABLE tenant_roles ENABLE ROW LEVEL SECURITY;
ALTER TABLE employees ENABLE ROW LEVEL SECURITY;
ALTER TABLE shifts ENABLE ROW LEVEL SECURITY;
ALTER TABLE absences ENABLE ROW LEVEL SECURITY;
ALTER TABLE compliance_violations ENABLE ROW LEVEL SECURITY;
ALTER TABLE audit_logs ENABLE ROW LEVEL SECURITY;
ALTER TABLE rta_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE payroll_rules ENABLE ROW LEVEL SECURITY;
ALTER TABLE payrolls ENABLE ROW LEVEL SECURITY;

ALTER TABLE tenant_roles FORCE ROW LEVEL SECURITY;
ALTER TABLE employees FORCE ROW LEVEL SECURITY;
ALTER TABLE shifts FORCE ROW LEVEL SECURITY;
ALTER TABLE absences FORCE ROW LEVEL SECURITY;
ALTER TABLE compliance_violations FORCE ROW LEVEL SECURITY;
ALTER TABLE audit_logs FORCE ROW LEVEL SECURITY;
ALTER TABLE rta_events FORCE ROW LEVEL SECURITY;
ALTER TABLE payroll_rules FORCE ROW LEVEL SECURITY;
ALTER TABLE payrolls FORCE ROW LEVEL SECURITY;

CREATE POLICY tenant_iso ON tenant_roles USING (tenant_id = current_setting('app.current_tenant', true)::uuid);
CREATE POLICY tenant_iso ON employees USING (tenant_id = current_setting('app.current_tenant', true)::uuid);
CREATE POLICY tenant_iso ON shifts USING (tenant_id = current_setting('app.current_tenant', true)::uuid);
CREATE POLICY tenant_iso ON absences USING (tenant_id = current_setting('app.current_tenant', true)::uuid);
CREATE POLICY tenant_iso ON compliance_violations USING (tenant_id = current_setting('app.current_tenant', true)::uuid);
