-- ============ REGLAS LEGALES INICIALES ============
INSERT INTO compliance_rules (rule_code, name, jurisdiction, norm_name, article_reference, source_url, severity, parameters, effective_from) VALUES
('ES_DAILY_REST_12H', 'Descanso diario 12h', 'ES', 'Estatuto de los Trabajadores', 'Art. 34.3', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11430', 'hard_stop', '{"min_rest_hours": 12}', '1995-01-01'),
