('ES_WEEKLY_REST_36H', 'Descanso semanal 36h', 'ES', 'Estatuto de los Trabajadores', 'Art. 37.1', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11430', 'hard_stop', '{"min_rest_hours": 36}', '1995-01-01'),
('EU_MAX_WEEKLY_48H', 'Maximo 48h/semana (UE)', 'EU', 'Directiva 2003/88/CE', 'Art. 6', 'https://eur-lex.europa.eu/legal-content/ES/TXT/?uri=CELEX:32003L0088', 'hard_stop', '{"max_weekly_hours": 48}', '2003-11-04'),
('ES_MAX_WEEKLY_40H', 'Maximo 40h/semana', 'ES', 'Estatuto de los Trabajadores', 'Art. 34.1', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11430', 'hard_stop', '{"max_weekly_hours": 40}', '1995-01-01'),
