-- Fuentes: ET (BOE-A-2015-11430), Dir 2003/88/CE, RD 1561/1995 (BOE-A-1995-21346)

CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- UUIDv7 generator
CREATE OR REPLACE FUNCTION uuidv7() RETURNS uuid AS $$
DECLARE ts bigint; b bytea;
BEGIN
    ts := (extract(epoch FROM clock_timestamp()) * 1000)::bigint;
    b := gen_random_bytes(16);
    b := set_byte(b, 0, (ts >> 40)::int);
    b := set_byte(b, 1, ((ts >> 32) & 255)::int);
    b := set_byte(b, 2, ((ts >> 24) & 255)::int);
    b := set_byte(b, 3, ((ts >> 16) & 255)::int);
    b := set_byte(b, 4, ((ts >> 8) & 255)::int);
    b := set_byte(b, 5, (ts & 255)::int);
    b := set_byte(b, 6, ((get_byte(b, 6) & 15) | 112));
    b := set_byte(b, 8, ((get_byte(b, 8) & 63) | 128));
    RETURN encode(b, 'hex')::uuid;
END; $$ LANGUAGE plpgsql VOLATILE;

-- TENANTS
CREATE TABLE tenants (
    id UUID PRIMARY KEY DEFAULT uuidv7(),
    name TEXT NOT NULL,
    slug TEXT NOT NULL UNIQUE,
    jurisdiction TEXT NOT NULL DEFAULT 'ES',
    timezone TEXT NOT NULL DEFAULT 'Europe/Madrid',
    currency TEXT NOT NULL DEFAULT 'EUR',
    plan TEXT NOT NULL DEFAULT 'starter',
    status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','suspended','deleted')),
    settings JSONB NOT NULL DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- USERS
CREATE TABLE users (
    id UUID PRIMARY KEY DEFAULT uuidv7(),
    email TEXT NOT NULL UNIQUE,
    password_hash TEXT,
    full_name TEXT NOT NULL,
