    role TEXT NOT NULL CHECK (role IN ('owner','admin','squad_lead','operator','employee','auditor','billing','integration')),
    granted_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at TIMESTAMPTZ,
    UNIQUE(tenant_id, user_id, role)
);

