    metadata JSONB NOT NULL DEFAULT '{}',
    occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    hash TEXT NOT NULL,
    previous_hash TEXT NOT NULL
);

-- Triggers anti-modificacion
CREATE OR REPLACE FUNCTION prevent_audit_mod() RETURNS trigger AS $$
BEGIN RAISE EXCEPTION 'audit_logs es inmutable: % no permitido', TG_OP; RETURN NULL; END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_audit_no_update BEFORE UPDATE ON audit_logs FOR EACH ROW EXECUTE FUNCTION prevent_audit_mod();
CREATE TRIGGER trg_audit_no_delete BEFORE DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION prevent_audit_mod();

-- Hash chain
CREATE OR REPLACE FUNCTION compute_audit_hash() RETURNS trigger AS $$
DECLARE prev TEXT; payload TEXT;
BEGIN
    SELECT hash INTO prev FROM audit_logs ORDER BY occurred_at DESC, id DESC LIMIT 1;
    IF prev IS NULL THEN prev := 'GENESIS'; END IF;
    payload := COALESCE(NEW.tenant_id::text,'') || '|' || NEW.action || '|' || NEW.resource_type || '|' || COALESCE(NEW.resource_id::text,'') || '|' || NEW.occurred_at::text || '|' || prev;
    NEW.previous_hash := prev;
    NEW.hash := encode(digest(payload, 'sha256'), 'hex');
    RETURN NEW;
END; $$ LANGUAGE plpgsql;

CREATE TRIGGER trg_audit_hash BEFORE INSERT ON audit_logs FOR EACH ROW EXECUTE FUNCTION compute_audit_hash();

